def populate_workflows(apps, schema_editor):
    Item = apps.get_model('core', 'CollectionLot')
    State = apps.get_model('core', 'UserLotWorkflow')
    alias = schema_editor.connection.alias
    # Preserve the furthest confirmed work when old memberships disagree.
    priority = {name:i for i,name in enumerate(('new','not_participated','interesting','applied','lost','won','contract','delivery','payment'))}
    winners = {}
    fields = ('stage','outcome','expired_from_stage','result_tracking')
    for item in Item.objects.using(alias).select_related('profile').order_by('updated_at','pk').iterator():
        key = (item.profile.owner_id,item.lot_id)
        old = winners.get(key)
        if old is None or priority.get(item.stage,0) >= priority.get(old.stage,0):
            winners[key] = item
    State.objects.using(alias).bulk_create([State(owner_id=owner,lot_id=lot,
        **{field:getattr(item,field) for field in fields}) for (owner,lot),item in winners.items()],batch_size=500)
    for (owner,lot),item in winners.items():
        Item.objects.using(alias).filter(profile__owner_id=owner,lot_id=lot).exclude(
            **{field:getattr(item,field) for field in fields}).update(**{field:getattr(item,field) for field in fields})


